"""Défis de fin de parcours : recherche et arguments au-delà de l'application."""
from pathlib import Path
import json,re
B=Path(__file__).resolve().parent.parent
D={}
def add(d,t,intro,qs):D.setdefault(d,[]).append((t,intro,qs))
def Q(q,m,r,a):return q,m,r,a
add('13_angles','Trois noms, un même sommet','Les points A, B, C et D définissent les angles ABC, CBD et ABD. Les deux petits angles ABC et CBD sont juxtaposés et remplissent ABD.',[
Q('Quel est leur sommet commun ?','Lire chaque lettre centrale.','ABC, CBD et ABD ont tous B au milieu.','B est le sommet commun.'),Q('Quel côté est commun aux deux petits angles ?','Comparer leurs deux demi-droites.','ABC a les côtés [BA) et [BC) ; CBD a les côtés [BC) et [BD).','Le côté [BC).'),Q('Comment obtenir ABD au calque ?','Juxtaposer les ouvertures indiquées.','Reporter ABC puis CBD autour de B, en faisant coïncider leurs côtés [BC) et sans recouvrement. Les côtés extrêmes sont [BA) et [BD).','Juxtaposer ABC et CBD ; les côtés extrêmes donnent ABD.')])
add('13_angles','Un classement à partir de moitiés','On fabrique le gabarit G en partageant un angle droit en deux par pliage. A vaut un G, B deux G et C trois G.',[
Q('Quelle mesure représente G ?','Partager 90 degrés en deux.','$90\\div2=45$.','$45^\\circ$.'),Q('Classer A, B et C.','Comparer les sommes au droit.','A vaut 45 degrés, B vaut $45+45=90$ degrés et C vaut $45+45+45=135$ degrés.','A aigu ; B droit ; C obtus.'),Q('Combien de G manque-t-il à C pour former un angle plat ?','Compléter jusqu’à deux angles droits.','Un angle plat contient quatre G ; C en contient trois, donc il en manque un.','Un gabarit G.')])
add('13_angles','Retrouver deux ouvertures','Deux angles A et B, juxtaposés, forment un angle droit. B est le double de A.',[
Q('Combien de copies de A remplissent l’angle droit ?','Remplacer B par deux copies de A.','A suivi de B revient à juxtaposer A, A et A.','Trois copies de A.'),Q('Calculer les mesures de A et B.','Partager puis doubler.','$90\\div3=30$ ; $2\\times30=60$.','$A=30^\\circ$ et $B=60^\\circ$.'),Q('Peut-on obtenir A en pliant une seule fois un angle droit en deux ?','Comparer le partage demandé et le pliage.','Le pliage en deux donne 45 degrés, alors que A vaut 30 degrés.','Non : un tel pli donne 45 degrés.')])
add('13_angles','Le gabarit retourné','Sur un calque, Noé reproduit un angle aigu. Il retourne le calque puis l’aligne au nouveau sommet, avec un côté sur la demi-droite donnée.',[
Q('L’ouverture change-t-elle quand on retourne le calque ?','Utiliser la superposition.','Retourner le calque ne déforme pas les côtés : l’angle est seulement présenté de l’autre côté.','Non, la même ouverture est conservée.'),Q('Pourquoi deux reproductions peuvent-elles se trouver de part et d’autre de la demi-droite ?','Repérer les positions possibles.','Le deuxième côté peut se tracer dans chacun des deux demi-plans ; les deux gabarits ont la même ouverture.','Il existe deux positions symétriques de même ouverture.'),Q('Quelle précision ajouter pour obtenir une seule position ?','Lever l’ambiguïté du programme.','Indiquer le côté de la demi-droite ou de la droite support où placer l’angle.','Préciser le côté où tracer le second côté de l’angle.')])
add('13_angles','Une ouverture de 135 degrés sans rapporteur','On dispose d’un coin de feuille et d’un calque, sans rapporteur.',[
Q('Fabriquer un gabarit de 45 degrés.','Plier le droit en deux.','Superposer les côtés du coin droit par pliage ; chaque moitié représente $90\\div2=45$ degrés.','Une moitié de coin droit.'),Q('Construire 135 degrés.','Juxtaposer le droit et sa moitié.','Reporter le coin droit, puis le demi-angle contre son dernier côté au même sommet, sans chevauchement : $90+45=135$.','Un droit suivi d’un demi-droit.'),Q('Retrouver cette ouverture à partir d’un angle plat.','Retirer une moitié d’angle droit.','Deux coins droits donnent 180 degrés. Retirer un gabarit de 45 degrés laisse $180-45=135$.','Un plat privé de 45 degrés.')])
add('13_angles','Deux pliages, puis une somme','On partage un angle droit en deux par pliage, puis chaque moitié encore en deux.',[
Q('Combien de petites parts égales obtient-on ?','Doubler le nombre de parts à chaque pliage.','Deux moitiés sont chacune partagées en deux : $2\\times2=4$.','Quatre parts égales.'),Q('Quelle est la mesure de trois petites parts ?','Calculer une part puis sa triple somme.','$90\\div4=22{,}5$ ; $3\\times22{,}5=67{,}5$.','$67{,}5^\\circ$.'),Q('Combien de petites parts faut-il ajouter pour retrouver le droit ?','Compléter quatre parts.','Trois des quatre petites parts sont déjà présentes ; $4-3=1$.','Une petite part de 22,5 degrés.')])
add('13_angles','Un éventail incomplet','Un éventail plat doit contenir huit secteurs égaux. Deux secteurs juxtaposés forment un angle droit. Pour l’instant, six secteurs sont présents.',[
Q('Quelle est la mesure d’un secteur ?','Partager l’angle droit.','Deux secteurs valent 90 degrés, donc un secteur vaut $90\\div2=45$ degrés.','$45^\\circ$.'),Q('La description de l’éventail plat est-elle possible ?','Comparer huit secteurs à un angle plat.','Huit secteurs de 45 degrés donnent $8\\times45=360$ degrés, tandis qu’un angle plat vaut 180 degrés.','Non : huit secteurs formeraient un tour complet, pas un angle plat.'),Q('Combien de ces secteurs faut-il pour un éventail plat ?','Chercher le nombre de 45 degrés dans 180 degrés.','$180\\div45=4$.','Quatre secteurs suffisent.')])

add('14_polygones','Le contour après découpage','Un pentagone a un coin découpé : une petite coupe droite relie deux points intérieurs aux deux côtés qui se rejoignaient en ce sommet. Aucun autre côté n’est touché.',[
Q('Combien de côtés a le nouveau contour ?','Suivre le bord après la coupe.','Les deux côtés concernés restent présents, mais raccourcis ; un nouveau côté, celui de la coupe, s’ajoute aux cinq anciens.','$5+1=6$ côtés.'),Q('Comment nommer la nouvelle figure ?','Relier le nombre de côtés au vocabulaire.','Un polygone à six côtés est un hexagone.','Un hexagone.'),Q('Est-il forcément régulier ?','Distinguer nombre de côtés et égalités.','La coupe ne garantit ni six côtés de même longueur ni six angles égaux.','Non : le découpage ne garantit aucune régularité.')])
add('14_polygones','Un triangle à deux propriétés','On construit ABC rectangle en A avec AB=AC=4 cm.',[
Q('Quels sont les deux noms justifiés ?','Lire les longueurs et l’angle droit.','AB=AC donne un triangle isocèle ; l’angle droit en A donne un triangle rectangle.','Triangle rectangle et isocèle en A.'),Q('Quels angles sont égaux ?','Utiliser les angles à la base de l’isocèle.','Les côtés égaux rejoignent A ; la base est [BC]. Les angles aux sommets B et C sont donc égaux.','Les angles ABC et ACB sont égaux.'),Q('Peut-il être équilatéral ?','Comparer les propriétés d’angles.','Un équilatéral possède trois angles égaux. Si l’un était droit, les trois seraient droits, ce qui ne forme pas un triangle plan.','Non, un triangle équilatéral n’a pas d’angle droit.')])
add('14_polygones','Le portrait qui manque une condition','Un quadrilatère a quatre côtés de 5 cm. Léa l’appelle carré sans vérifier les angles.',[
Q('Quel nom est déjà certain ?','Utiliser uniquement les informations garanties.','Quatre côtés de même longueur définissent un losange.','C’est un losange.'),Q('Quelle vérification permettrait de conclure carré ?','Ajouter la propriété du carré qui manque.','Il faut contrôler à l’équerre les quatre angles droits.','Vérifier les quatre angles droits.'),Q('Quel exemple montre que Léa peut se tromper ?','Chercher un losange sans angle droit.','Un losange aplati possède quatre côtés égaux mais des angles aigus et obtus.','Un losange sans angle droit est un contre-exemple.')])
add('14_polygones','Assembler un trapèze rectangle','On accole un triangle rectangle à droite d’un rectangle de 4 cm sur 3 cm. Le triangle a ses côtés perpendiculaires de 2 cm à l’horizontale et de 3 cm à la verticale. Le côté vertical est commun aux deux pièces.',[
Q('Quelles sont les longueurs des bases du contour assemblé ?','Suivre les bords horizontaux.','Le bord du bas réunit 4 cm et 2 cm ; le bord du haut garde les 4 cm du rectangle.','Bases de 6 cm et 4 cm.'),Q('Pourquoi obtient-on un trapèze rectangle ?','Repérer une paire parallèle et deux angles droits.','Les deux bases sont horizontales donc parallèles. Les deux coins de gauche restent les angles droits du rectangle.','Il a deux bases parallèles et deux angles droits.'),Q('Le côté commun fait-il partie du contour ?','Distinguer bord extérieur et séparation intérieure.','Le segment partagé se trouve à l’intérieur de l’assemblage ; il sépare les deux pièces.','Non : le côté commun est intérieur.')])
add('14_polygones','Un carré à plusieurs noms','Un quadrilatère ABCD a quatre angles droits et quatre côtés égaux.',[
Q('Justifier trois noms de figures usuelles.','Tester chaque définition.','Quatre angles droits donnent rectangle ; quatre côtés égaux donnent losange ; réunir les deux donne carré.','Carré, rectangle et losange.'),Q('Possède-t-il une paire de côtés opposés parallèles ?','Utiliser les propriétés du carré.','Dans un carré, les deux paires de côtés opposés sont parallèles.','Oui : AB est parallèle à CD et AD à BC.'),Q('Avec la définition du cours, est-il aussi un trapèze ?','Appliquer la condition de parallélisme.','Le cours appelle trapèze un quadrilatère possédant une paire de côtés opposés parallèles ; le carré satisfait cette condition.','Oui, avec cette définition inclusive du trapèze.')])
add('14_polygones','Deux triangles isocèles au compas','Trace [AB] de 6 cm. Trace deux cercles, de centres A et B, tous deux de rayon 5 cm. Nomme C leur intersection au-dessus de (AB), et D celle en dessous.',[
Q('Pourquoi ABC et ABD sont-ils isocèles ?','Utiliser les rayons des cercles.','AC=BC=5 cm et AD=BD=5 cm : chaque triangle possède deux côtés égaux.','Ils sont isocèles, de base [AB].'),Q('Quel est le nom du quadrilatère ACBD ?','Suivre les quatre côtés dans l’ordre donné.','AC, CB, BD et DA mesurent tous 5 cm. Quatre côtés égaux définissent un losange.','ACBD est un losange.'),Q('Son périmètre dépend-il des 6 cm de AB ?','Reconnaître les côtés et la diagonale.','AB est une diagonale du losange, pas un côté. Le contour comporte quatre côtés de 5 cm : $5+5+5+5=20$.','Non : le périmètre est 20 cm.')])
add('14_polygones','Le rectangle et ses deux moitiés','Un rectangle ABCD mesure 9 cm sur 5 cm. On trace sa diagonale [AC], puis on découpe suivant ce segment.',[
Q('Nommer les deux triangles et leurs angles droits.','Suivre les deux contours.','La première pièce a pour sommets A,B,C et l’angle droit B ; la seconde A,C,D et l’angle droit D.','ABC rectangle en B ; ACD rectangle en D.'),Q('Peut-on superposer les deux pièces ?','Comparer les côtés correspondants.','Le rectangle possède des côtés opposés égaux : AB=CD, BC=AD, et AC est commun. En retournant une pièce, les contours se superposent.','Oui, les deux triangles sont superposables.'),Q('Pourquoi additionner leurs périmètres ne donne-t-il pas celui du rectangle ?','Repérer le bord créé par le découpage.','Le segment AC apparaît dans le contour de chaque triangle ; il est compté deux fois alors qu’il est intérieur au rectangle.','La diagonale serait comptée deux fois en trop.')])

add('15_constructions','Un rectangle puis son cercle','Construis ABCD de longueur 6 cm et largeur 4 cm. M est le milieu de [AB]. On veut le cercle de centre M passant par A.',[
Q('Rédiger le programme du rectangle.','Fixer la base et les perpendiculaires.','Tracer AB=6 cm ; élever les perpendiculaires à (AB) en A et B ; placer D et C à 4 cm, du même côté ; joindre D à C.','AB=6 cm, AD=BC=4 cm et quatre angles droits.'),Q('Où placer M et quelle ouverture choisir ?','Utiliser le milieu.','$6\\div2=3$ : M est sur [AB] à 3 cm de A et B. Le rayon MA vaut donc 3 cm.','M à 3 cm de A ; compas ouvert à 3 cm.'),Q('Le cercle passe-t-il aussi par B ?','Comparer MB au rayon.','MA=MB=3 cm ; B est donc à la distance du rayon du centre M.','Oui, B appartient au cercle.')])
add('15_constructions','Un trapèze construit par deux directions','On veut ABCD avec AB=8 cm et DC=5 cm parallèles ; AD=3 cm et perpendiculaire aux deux bases.',[
Q('Décrire les trois premiers tracés.','Commencer par une base et sa perpendiculaire.','Tracer AB=8 cm ; tracer la perpendiculaire en A ; y placer D à 3 cm de A.','[AB], la perpendiculaire en A, puis D à 3 cm.'),Q('Comment placer C ?','Utiliser une parallèle et la longueur de la seconde base.','Tracer la parallèle à (AB) passant par D. Placer C à 5 cm de D, dans la direction de A vers B. Joindre C à B.','C sur la parallèle par D avec DC=5 cm.'),Q('Pourquoi la figure n’est-elle pas un rectangle ?','Comparer les côtés opposés.','Les bases AB=8 cm et DC=5 cm ne sont pas de même longueur, alors que les côtés opposés d’un rectangle le sont.','Les bases de 8 cm et 5 cm sont différentes.')])
add('15_constructions','Un point soumis à deux distances','On trace [AB] de 6 cm. C doit être à 5 cm de A et à 5 cm de B, au-dessus de la droite (AB).',[
Q('Quels cercles permettent de trouver C ?','Transformer chaque distance en condition de cercle.','Les points à 5 cm de A sont sur le cercle de centre A ; ceux à 5 cm de B sont sur le cercle de centre B.','Deux cercles de rayon 5 cm, de centres A et B.'),Q('Quelle intersection faut-il choisir ?','Appliquer la précision de position.','Les deux cercles ont une intersection de chaque côté de la droite ; la consigne choisit celle du dessus.','L’intersection au-dessus de (AB).'),Q('Que manque-t-il à la consigne « C est à 5 cm de A » ?','Chercher si un seul point est désigné.','Tous les points du cercle de centre A et rayon 5 cm conviennent ; il en existe une infinité.','Une seconde condition pour choisir C.')])
add('15_constructions','Un carré inscrit dans son programme','On veut construire un carré ABCD de côté 4 cm. Tom place C et D de part et d’autre de la droite (AB), chacun sur la perpendiculaire correspondante.',[
Q('Pourquoi le tracé de Tom ne donne-t-il pas le carré attendu ?','Contrôler le contour dans l’ordre A,B,C,D.','Les deux sommets doivent être dans le même demi-plan pour fermer le carré ABCD ; les placer de part et d’autre crée un contour qui se croise.','C et D doivent être du même côté de (AB).'),Q('Rédiger l’instruction corrigée.','Donner longueur et position.','Sur les perpendiculaires en A et B, placer D et C à 4 cm de A et B, du même côté de (AB).','AD=BC=4 cm, C et D du même côté.'),Q('Quels contrôles garantissent un carré ?','Associer les deux conditions du carré.','Vérifier les quatre côtés de 4 cm et les quatre angles droits.','Quatre côtés égaux et quatre angles droits.')])
add('15_constructions','Un triangle rectangle avec une distance à B','Trace AB=6 cm. On veut ABC rectangle en A, avec BC=10 cm et C au-dessus de (AB).',[
Q('Sur quelle droite se trouve C ?','Utiliser l’angle droit en A.','AC doit être perpendiculaire à AB, donc C se trouve sur la perpendiculaire à (AB) passant par A.','La perpendiculaire à (AB) en A.'),Q('Comment obtenir C au compas ?','Utiliser la distance au centre B.','Tracer le cercle de centre B et rayon 10 cm ; choisir son intersection avec la perpendiculaire en A, au-dessus de (AB).','Intersection de la perpendiculaire et du cercle de centre B, rayon 10 cm.'),Q('Que vérifier sur la figure finale ?','Contrôler chaque donnée initiale.','Mesurer AB et BC, puis vérifier à l’équerre l’angle BAC.','AB=6 cm, BC=10 cm et angle droit en A.')])
add('15_constructions','Le programme inexécutable','Voici le programme de Zoé : 1. Tracer le cercle de centre O passant par M. 2. Tracer AB=8 cm. 3. Placer M milieu de [AB] et O à 3 cm au-dessus de M.',[
Q('Pourquoi la première instruction est-elle impossible au départ ?','Chercher les points déjà définis.','Ni O ni M ne sont placés ; on ne peut pas fixer le centre ni le rayon.','O et M n’existent pas encore.'),Q('Proposer un ordre exécutable.','Créer les points avant de les employer.','Tracer AB, puis M et O, puis le cercle.','2, 3, 1.'),Q('Quelle information préciser si « au-dessus » ne suffit pas ?','Définir une direction exacte.','Pour placer O sans ambiguïté, imposer qu’il soit sur la perpendiculaire à (AB) passant par M, du côté choisi.','Préciser la perpendiculaire en M et OM=3 cm.')])
add('15_constructions','Deux cercles et un disque','Trace AB=8 cm et son milieu M. Trace le cercle de centre A passant par M et celui de centre B passant par M.',[
Q('Quels sont leurs rayons ?','Partager AB en deux.','AM=BM=$8\\div2=4$ cm.','Les deux rayons mesurent 4 cm.'),Q('B appartient-il au disque de centre A correspondant ?','Comparer AB au rayon.','AB=8 cm est supérieur au rayon de 4 cm ; B est au-delà du disque.','Non, B est extérieur au disque de centre A.'),Q('Comment obtenir les cercles de même centre et de diamètre 8 cm ?','Relier rayon et diamètre.','Un diamètre de 8 cm correspond à un rayon de $8\\div2=4$ cm ; ce sont précisément les cercles déjà tracés.','Aucune modification : ils ont déjà un diamètre de 8 cm.')])

add('16_symetrie','Le triangle devant le miroir vertical','Sur quadrillage, trace un axe vertical. A est à 1 carreau à gauche de l’axe ; B est sur la même ligne, à 4 carreaux à gauche ; C est 3 carreaux au-dessus de A. Relie A,B,C.',[
Q('Décrire A’ et B’.','Reporter chaque distance de l’autre côté.','A’ est à 1 carreau à droite et B’ à 4, sur la ligne de A et B.','A’ à 1 carreau à droite ; B’ à 4 carreaux à droite.'),Q('Où est C’ par rapport à A’ ?','Conserver la position sur les lignes.','C se trouve au-dessus de A et sur la même colonne. Pour un axe vertical, les hauteurs sont conservées.','C’ est 3 carreaux au-dessus de A’.'),Q('Quelle est la longueur A’B’ ?','Calculer AB puis conserver la longueur.','$AB=4-1=3$ carreaux, donc A’B’ a aussi cette longueur.','3 côtés de carreaux.')])
add('16_symetrie','Le rectangle sous l’axe','Un rectangle de 5 carreaux sur 2 carreaux est entièrement au-dessus d’un axe horizontal. Son bord le plus proche est à 1 carreau de l’axe.',[
Q('À quelle distance de l’axe seront les deux bords horizontaux de son image ?','Reporter les distances correspondantes.','Le bord proche est à 1 carreau ; le bord éloigné est à $1+2=3$ carreaux. Les mêmes distances sont reportées en dessous.','À 1 et 3 carreaux en dessous.'),Q('Quelles dimensions aura le rectangle image ?','Utiliser la conservation des longueurs.','La symétrie ne déforme pas la figure, donc ses deux dimensions restent 5 et 2 carreaux.','5 carreaux sur 2 carreaux.'),Q('Quelle distance verticale sépare les deux bords les plus proches des deux rectangles ?','Ajouter les distances à l’axe.','Chaque bord proche est à 1 carreau de son côté de l’axe : $1+1=2$.','2 côtés de carreaux.')])
add('16_symetrie','Le triangle et la diagonale','Sur quadrillage, O est sur une diagonale montant vers la droite. Depuis O : A est à 4 carreaux à droite et 1 en haut ; B à 5 à droite et 1 en haut ; C à 4 à droite et 3 en haut.',[
Q('Donner les trajets vers A’ et B’.','Échanger horizontal et vertical depuis O.','Le trajet (4 à droite,1 en haut) devient (1 à droite,4 en haut) ; (5,1) devient (1,5).','A’ : 1 à droite, 4 en haut ; B’ : 1 à droite, 5 en haut.'),Q('Donner le trajet vers C’.','Appliquer la même règle au troisième sommet.','C est obtenu par 4 à droite et 3 en haut ; son image échange les deux nombres.','3 à droite puis 4 en haut.'),Q('Les segments AB et A’B’ ont-ils la même direction ?','Comparer les trajets entre sommets.','AB avance d’un carreau à droite ; A’B’ avance d’un carreau vers le haut. Les longueurs sont égales mais les directions diffèrent.','Non : AB est horizontal et A’B’ vertical.')])
add('16_symetrie','Reconstruire la figure initiale','On connaît une figure image A’B’C’ par rapport à un axe vertical. A’ est à 2 carreaux à droite, B’ à 5 à droite sur la même ligne, C’ à 2 à droite et 3 lignes plus haut.',[
Q('Comment retrouver les sommets de départ ?','Faire le même pliage dans le sens inverse.','La symétrie est réciproque : reporter chaque point à gauche, à la même distance et sur la même ligne.','A à 2 carreaux à gauche, B à 5 à gauche ; C à 2 à gauche et 3 lignes plus haut.'),Q('Quelle est la nature du triangle ABC ?','Repérer l’angle droit sur le quadrillage.','AB est horizontal et AC vertical ; ils sont donc perpendiculaires.','ABC est rectangle en A.'),Q('Deux symétries successives par rapport au même axe changent-elles la figure ?','Suivre un point aller puis retour.','La première symétrie fait traverser l’axe ; la seconde le fait retraverser de la même distance vers son emplacement initial.','Non : on retrouve la figure initiale.')])
add('16_symetrie','Une diagonale du rectangle','On découpe un rectangle de 6 carreaux sur 4 et on propose sa diagonale comme axe de symétrie.',[
Q('Pourquoi deux triangles de même aire ne suffisent-ils pas ?','Distinguer aire et pliage.','Deux pièces peuvent avoir la même aire sans se superposer par le pliage imposé.','L’égalité des aires ne garantit pas la superposition sur cet axe.'),Q('La diagonale est-elle un axe de ce rectangle ?','Tester les côtés adjacents au sommet.','Le pliage suivant la diagonale devrait faire coïncider le côté de 6 carreaux et celui de 4 ; leurs longueurs sont différentes.','Non : les côtés de 6 et 4 ne se superposent pas.'),Q('Quelles droites sont ses axes ?','Chercher les pliages correspondant aux côtés opposés.','Les deux lignes passant par les milieux des côtés opposés superposent exactement le rectangle.','Deux axes : les lignes médianes horizontale et verticale.')])
add('16_symetrie','Le symétrique qui a seulement glissé','Un axe est vertical. A est 3 carreaux à gauche et B 1 carreau à gauche, sur la même ligne. Jade déplace chaque point de 4 carreaux à droite.',[
Q('Où Jade place-t-elle les deux points ?','Suivre le déplacement annoncé.','A traverse les 3 carreaux jusqu’à l’axe puis avance encore 1 ; B traverse 1 carreau puis avance encore 3.','Elle place l’image de A à 1 carreau à droite et celle de B à 3 carreaux à droite.'),Q('Ces points sont-ils les bons symétriques ?','Comparer les distances à l’axe point par point.','A doit rester à 3 carreaux de l’axe et B à 1 ; Jade a échangé ces distances.','Non : A’ doit être à 3 carreaux à droite, B’ à 1.'),Q('Pourquoi la même longueur entre les deux points ne suffit-elle pas ?','Vérifier les conditions de chaque paire.','La distance entre les deux points est conservée par un glissement aussi. Il faut en plus que chaque point et son image soient à égale distance de l’axe.','Il faut contrôler chaque point avec son propre symétrique.')])
add('16_symetrie','Deux miroirs et une figure entière','Deux axes, vertical et horizontal, se croisent en O. Un petit carré est placé entièrement en haut à droite, son sommet le plus proche étant à 1 carreau à droite et 2 au-dessus de O. Son côté mesure 2 carreaux.',[
Q('Où est ce sommet après la symétrie verticale ?','Changer seulement gauche et droite.','La hauteur reste de 2 carreaux ; 1 carreau à droite devient 1 à gauche.','À 1 carreau à gauche et 2 au-dessus de O.'),Q('Où est-il après une seconde symétrie horizontale ?','Changer ensuite haut et bas.','La position à gauche est conservée et les 2 carreaux au-dessus deviennent 2 en dessous.','À 1 carreau à gauche et 2 en dessous de O.'),Q('Quelle est la taille de la figure finale ?','Utiliser deux fois la conservation des longueurs.','Chaque symétrie conserve la forme et le côté de 2 carreaux.','Un carré de côté 2 carreaux, en bas à gauche.')])

add('17_solides','Même inventaire, formes différentes','Deux solides possèdent chacun 6 faces, 12 arêtes et 8 sommets. Le premier a toutes ses arêtes de 3 cm. Le second est un pavé droit de dimensions 3, 4 et 5 cm.',[
Q('Quel est le nom du premier, s’il s’agit d’un pavé droit ?','Associer l’égalité des arêtes à la famille.','Un pavé droit dont toutes les arêtes ont la même longueur possède six faces carrées égales.','C’est un cube.'),Q('Le second est-il aussi un cube ?','Comparer les longueurs des arêtes.','Les trois dimensions 3,4 et5 cm ne sont pas égales ; certaines faces ne sont pas carrées.','Non : c’est un pavé droit non cubique.'),Q('Le nombre de sommets suffit-il à distinguer cube et pavé ?','Comparer les deux inventaires.','Les deux solides possèdent huit sommets, malgré leurs dimensions différentes.','Non, il faut aussi décrire les faces ou les dimensions.')])
add('17_solides','Un prisme mystérieux','Un prisme droit possède 7 faces en tout.',[
Q('Combien a-t-il de faces latérales ?','Retirer les deux bases.','Deux des sept faces sont les bases ; $7-2=5$.','5 faces latérales rectangulaires.'),Q('Quelle est la forme des bases ?','Relier faces latérales et côtés de base.','Chaque côté d’une base correspond à une face latérale. Les bases ont donc cinq côtés.','Des pentagones.'),Q('Combien a-t-il de sommets et d’arêtes ?','Compter dans les deux bases puis entre elles.','Sommets : $5+5=10$. Arêtes : 5 sur chaque base et5 entre les bases, donc $5+5+5=15$.','10 sommets et 15 arêtes.')])
add('17_solides','Deux solides à cinq faces','Un prisme droit à base triangulaire et une pyramide à base carrée ont chacun cinq faces.',[
Q('Décrire les cinq faces de chacun.','Séparer bases et faces latérales.','Le prisme a2 triangles et3 rectangles. La pyramide a1 carré et4 triangles.','Prisme : 2 triangles et3 rectangles ; pyramide : 1 carré et4 triangles.'),Q('Leurs nombres de sommets sont-ils égaux ?','Compter les sommets des bases et le sommet principal.','Le prisme a $3+3=6$ sommets. La pyramide a $4+1=5$ sommets.','Non : 6 pour le prisme, 5 pour la pyramide.'),Q('Quel indice permet de reconnaître la pyramide ?','Repérer le point commun aux faces latérales.','Toutes ses faces triangulaires latérales se rejoignent en un même sommet principal.','Les triangles latéraux se rejoignent au sommet principal.')])
add('17_solides','Le sommet oublié dans la perspective','Sur le dessin d’un pavé droit, on voit les faces avant, droite et supérieure. Le sommet arrière, inférieur et gauche est caché.',[
Q('Combien d’arêtes rejoignent ce sommet caché ?','Suivre les trois directions du pavé.','À chaque sommet du pavé, trois arêtes se rencontrent : une selon chaque dimension.','Trois arêtes.'),Q('Quels traits faut-il employer pour ces arêtes ?','Coder ce qui est derrière les faces.','Ces trois arêtes sont invisibles depuis le point de vue choisi ; on les représente en pointillés.','Trois traits en pointillés.'),Q('Si on omet ces traits, combien d’arêtes le dessin semble-t-il montrer ?','Retirer les arêtes cachées du total.','Le pavé possède12 arêtes ; sans les3 cachées, il en reste $12-3=9$ dessinées.','9, mais le solide en possède toujours12.')])
add('17_solides','Les faces d’un dé à compléter','Un patron de cube comporte quatre carrés en rangée : A,B,C,D. Un carré E est au-dessus de B et un carré F en dessous. Les faces opposées du dé doivent porter des nombres dont la somme est7. A porte1, B porte2 et E porte3.',[
Q('Quelles lettres sont opposées après pliage ?','Replier mentalement la bande et les deux couvercles.','La bande donne les paires A/C et B/D ; les couvercles E et F sont opposés.','A/C, B/D et E/F.'),Q('Quels nombres écrire dans C et D ?','Compléter chaque somme jusqu’à7.','C est opposée à A=1 : $7-1=6$. D est opposée à B=2 : $7-2=5$.','C=6 et D=5.'),Q('Quel nombre écrire dans F et comment contrôler ?','Compléter la dernière paire puis vérifier les trois sommes.','$7-3=4$ ; les sommes sont $1+6=7$, $2+5=7$ et $3+4=7$.','F=4 ; les trois sommes valent7.')])
add('17_solides','Le patron incomplet d’un pavé','On veut une boîte de6 cm sur4 cm sur3 cm. Une élève a déjà découpé deux rectangles de6 sur4 et deux de6 sur3.',[
Q('Quelles faces manque-t-il ?','Compléter les trois paires de faces.','Les paires longueur-largeur et longueur-hauteur sont présentes ; il manque les faces largeur-hauteur.','Deux rectangles de4 cm sur3 cm.'),Q('Pourquoi quatre rectangles ne suffisent-ils pas ?','Compter les faces du pavé fermé.','Un pavé fermé possède6 faces ; $6-4=2$ restent manquantes.','Il manque deux faces pour fermer la boîte.'),Q('Les bonnes dimensions suffisent-elles à valider le patron ?','Contrôler aussi la disposition.','Même six rectangles corrects peuvent se chevaucher au pliage s’ils sont mal disposés. Il faut vérifier leur assemblage et le repliement.','Non : il faut tester le pliage sans trou ni superposition.')])
add('17_solides','Les cubes invisibles de la réserve','Une réserve pleine a4 rangées de3 cubes par couche et3 couches. On retire ensuite deux colonnes complètes, chacune haute de3 cubes.',[
Q('Combien de cubes contient la réserve avant retrait ?','Compter une couche puis les trois couches.','$4\\times3=12$ cubes par couche ; $12\\times3=36$.','36 cubes.'),Q('Combien de cubes retire-t-on ?','Compter les colonnes enlevées.','Deux colonnes de3 cubes font $2\\times3=6$ cubes.','6 cubes.'),Q('Combien restent-ils et pourquoi la vue de dessus ne suffit-elle pas à les compter directement ?','Soustraire puis distinguer emplacement et hauteur.','$36-6=30$. La vue de dessus indique les colonnes occupées, sans montrer leurs trois niveaux.','30 cubes ; la vue de dessus cache les niveaux inférieurs.')])

