    for d,items in D.items():
        p=B/d/'exercices.txt';blocks=[b for b in re.split(r'^===\s*$',p.read_text(encoding='utf-8'),flags=re.M) if b.strip()]
        assert len(blocks)==21
        cor=json.loads((B/d/'figures/correspondance.json').read_text(encoding='utf-8'))
        for n,(t,intro,qs) in enumerate(items,15):
            text=f'=== Problème - {t}\nId: nouveau-{n}\nDifficulté: hard\nÉnoncé:\n<!-- optitab:1 -->\n{intro}\n\n'
            text+='\n'.join(f'{i}. {q[0]}' for i,q in enumerate(qs,1))+'\n\nÉtapes:\n<!-- optitab:1 -->\n'
            for i,(q,m,r,a) in enumerate(qs,1):text+=f'## Question {i} : {q}\n\n::: methode\n{m}\n:::\n\n::: etape Raisonnement\n{r}\n:::\n\n::: resultat\n{a}\n:::\n\n'
            text+='Solution:\n<!-- optitab:1 -->\n'+'\n'.join(f'{i}. {q[3]}' for i,q in enumerate(qs,1))+'\n'
            blocks[n-1]=text;cor['exercices'].pop(f'nouveau-{n}',None)
        p.write_text('\n===\n\n'.join(b.strip() for b in blocks)+'\n===\n',encoding='utf-8')
        (B/d/'figures/correspondance.json').write_text(json.dumps(cor,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
        print(d,len(items),'défis enrichis')
